// aplexer awareness plugin (generated by scripts/package-coordination.py).
//
// Surfaces aplexer coordination context (unread sibling mail, active work
// declarations) by calling `a context hook --engine opencode` at tool
// boundaries and appending the returned text to the tool's model-facing
// output (tool.execute.after's output.output is mutable). Best-effort:
// failures never break the tool result. Re-generating the bundle refreshes
// this file; nothing here touches user config.
import child_process from "node:child_process";

const A = "__APLEXER_BIN__";

export const AplexerCoordination = async () => {
  const pending = new Map();
  const key = (input) => `${input?.sessionID ?? ""}:${input?.callID ?? ""}`;
  return {
    "tool.execute.before": async (input, output) => {
      const args = output?.args;
      const safe = {};
      for (const name of ["workdir", "cwd", "directory", "file_path", "path", "filePath"]) {
        if (typeof args?.[name] === "string") {
          safe[name === "filePath" ? "file_path" : name] = args[name];
        }
      }
      if (pending.size >= 512) pending.delete(pending.keys().next().value);
      pending.set(key(input), safe);
    },
    "tool.execute.after": async (input, output) => {
      const tool_input = pending.get(key(input));
      pending.delete(key(input));
      try {
        const payload = JSON.stringify({
          hook_event_name: "tool.execute.after",
          tool_input,
          tool_name: input?.tool ?? input?.tool_name ?? "",
          session_id: input?.sessionID ?? globalThis.process?.env?.APLEXER_SESSION_ID ?? "",
        });
        const r = child_process.spawnSync(
          A,
          ["context", "hook", "--engine", "opencode"],
          { input: payload, encoding: "utf8", timeout: 5000 },
        );
        if (
          r.status === 0 &&
          r.stdout &&
          r.stdout.trim() &&
          output &&
          typeof output === "object" &&
          typeof output.output === "string"
        ) {
          // Append only: the original tool result is preserved byte-for-byte.
          output.output += "\n\n" + r.stdout.trim() + "\n";
        }
      } catch (e) {
        // best-effort; never throw out of a plugin hook
      }
    },
  };
};
